    88	export function observeNativeHostProcess(startPid = process.ppid): NativeHostProcessObservation | null {
    89	  if (process.platform === 'win32') return null;
    90	  let pid = startPid;
    91	  const lineage: NativeHostProcessLineageRow[] = [];
    92	  const seen = new Set<number>();
    93	  let complete = false;
    94	  for (let depth = 0; depth < 32 && Number.isInteger(pid) && pid > 1 && !seen.has(pid); depth += 1) {
    95	    seen.add(pid);
    96	    let raw: string;
    97	    try {
    98	      raw = execFileSync('ps', ['-o', 'ppid=', '-o', 'comm=', '-o', 'command=', '-p', String(pid)], {
