   101	        stdio: ['ignore', 'pipe', 'ignore'],
   102	      }).trim();
   103	    } catch {
   104	      return null;
   105	    }
   106	    const match = raw.match(/^\s*(\d+)\s+(\S+)\s+(.+)$/s);
   107	    if (!match) return null;
