  1607	      const paths = pathsFor(root, run.runId);
  1608	      const archivePath = managedHostRunReceiptArchivePath(root, run.runId);
  1609	      mkdirSync(managedHostRunReceiptsRoot(root), { recursive: true, mode: 0o700 });
  1610	      const archive: ManagedHostRunReceiptArchive = {
  1611	        schemaVersion: 'lattice.managed_host_run_receipt_archive.v1',
  1612	        runId: run.runId,
  1613	        archivedAt: run.terminalAt ?? new Date(options.now ?? Date.now()).toISOString(),
  1614	        receipt: managedHostRunReceipt(root, run.runId),
  1615	        evidenceBindingDigest: digestFile(paths.evidenceBinding),
  1616	      };
