   274	    && proposal.lane === args.lane
   275	    && args.binding.lane === args.lane
   276	    && args.binding.reviewRunId === args.reviewRunId
   277	    && proposal.reviewRunId === args.reviewRunId
   278	    && runBinding.profile === 'managed_reviewer'
   279	    && runBinding.host === args.binding.providerHost
   280	    && runBinding.agentType === args.agent
   281	    && runBinding.lane === args.lane
   282	    && runBinding.reviewRunId === args.reviewRunId;
   283	  const reviewTupleMatches = runBinding.reviewBinding !== null
   284	    && runBinding.reviewBinding.headHash === args.expected.headHash
   285	    && runBinding.reviewBinding.materialHash === args.expected.materialHash
   286	    && runBinding.reviewBinding.storyFilesHash === args.expected.storyFilesHash
   287	    && runBinding.reviewBinding.promptHash === args.expected.promptHash
   288	    && runBinding.reviewBinding.envelopeId === args.expected.envelopeId
   289	    && args.binding.headHash === args.expected.headHash
   290	    && args.binding.materialHash === args.expected.materialHash
   291	    && args.binding.storyFilesHash === args.expected.storyFilesHash
   292	    && args.binding.promptHash === args.expected.promptHash
   293	    && args.binding.envelopeId === args.expected.envelopeId
   294	    && runBinding.promptDigest === args.expected.managedPromptDigest;
   295	  const storyMatches = proposal?.storyId === args.storyId
   296	    && runBinding.storyId === args.storyId;
   297	  const diagnostic = buildProofAdmissibilityDiagnostic({
   298	    artifactKind: 'managed-review-evidence',
   299	    artifactId: args.binding.receiptId,
   300	    consumer: 'REVIEW',
   301	    claim: 'review-pass',
   302	    mode: 'enforce',
   303	    enforcedConsumers: ['REVIEW'],
   304	    checks: {
   305	      schemaVersion: args.binding.schemaVersion,
   306	      strictShapeValid: shapeValid,
   307	      semanticDigestValid,
