   642	/** A terminal writer may legitimately outlive staleMs; PID reuse is fenced by process start time. */
   643	export function classifyManagedHostRunTerminalLock(snapshot: ExistingMkdirLockSnapshot): ExistingMkdirLockState {
   644	  const holder = snapshot.holder;
   645	  if (!holder || holder.hostname !== hostname()) return 'unknown';
   646	  if (!Number.isInteger(holder.pid) || holder.pid <= 0) return 'unknown';
   647	  try {
   648	    process.kill(holder.pid, 0);
   649	  } catch (error) {
   650	    const code = (error as NodeJS.ErrnoException).code;
   651	    if (code === 'ESRCH') return 'stale';
   652	    if (code !== 'EPERM') return 'unknown';
   653	  }
   654	  const observedStart = processStartTimeMsForPid(holder.pid);
   655	  if (!sameProcessStart(holder.processStartTimeMs, observedStart)) return 'stale';
   656	  // A live PID with an unobservable start time is conservatively active. The
   657	  // bounded acquisition deadline reports contention instead of stealing it.
   658	  return 'active';
   659	}
