   661	function writeTerminal(
   662	  paths: ManagedHostRunPaths,
   663	  state: ManagedHostRunTerminalState,
   664	  reason: string,
   665	  replacementSafe: boolean,
   666	  result: HostRunResult | null,
   667	  now: number,
   668	): ManagedHostRunTerminal {
   669	  return withMkdirLock(paths.terminalLock, () => {
   670	    const existing = readTerminal(paths);
   671	    if (existing) return existing;
   672	
   673	    if (result) atomicWrite(paths.result, result);
   674	    const specText = readFileSync(paths.spec, 'utf8');
   675	    const snapshot = readJson<ManagedHostRunSnapshot>(paths.snapshot);
   676	    const terminal: ManagedHostRunTerminal = {
   677	      schemaVersion: MANAGED_HOST_RUN_SCHEMA_VERSION,
   678	      runId: snapshot.runId,
   679	      state,
   680	      reason,
   681	      terminalAt: new Date(now).toISOString(),
   682	      generation: snapshot.generation + 1,
   683	      replacementSafe,
   684	      resultDigest: digestFile(paths.result),
   685	      eventJournalDigest: digestFile(paths.events) ?? sha256(''),
   686	      specDigest: sha256(specText),
   687	      evidenceProposalDigest: digestFile(paths.evidenceProposal),
   688	      processCleanup: result?.processCleanup ?? (
   689	        replacementSafe
   690	          ? { termSent: false, killSent: false, reaped: true, residualProcessGroup: false }
   691	          : null
   692	      ),
   693	    };
   694	    if (!writeExclusive(paths.terminal, terminal)) return readJson<ManagedHostRunTerminal>(paths.terminal);
   695	    updateSnapshot(paths, current => ({
   696	      ...current,
   697	      state: terminal.state,
   698	      generation: terminal.generation,
   699	      replacementSafe: terminal.replacementSafe,
   700	    }));
   701	    // terminal.json is the exclusive terminal event. Keep events.jsonl immutable
   702	    // after its digest is sealed into the terminal receipt; appending a second
   703	    // textual terminal event here would immediately make eventJournalDigest stale.
   704	    return terminal;
   705	  }, {
   706	    label: `managed terminal ${paths.dir}`,
   707	    deadlineMs: 5_000,
   708	    staleMs: 2_000,
   709	    pollMs: 10,
   710	    requireHolderToken: true,
   711	    classifyExistingLock: classifyManagedHostRunTerminalLock,
   712	    holderInfo: {
   713	      pid: process.pid,
   714	      hostname: hostname(),
   715	      command: `managed terminal ${paths.dir}`,
   716	      acquiredAt: new Date().toISOString(),
   717	      lockId: randomUUID(),
   718	      processStartTimeMs: currentProcessStartTimeMs(),
   719	    },
   720	  });
   721	}
