   723	/**
   724	 * Production launcher. The prompt and capability remain files inside the run
   725	 * directory; only root and runId cross argv. stdout/stderr are append-only
   726	 * worker diagnostics, not the provider live-output protocol.
   727	 */
   728	export const defaultManagedHostRunWorkerLauncher: ManagedHostRunWorkerLauncher = request => {
   729	  assertManagedHostRunPlatformSupported(process.platform);
   730	  const paths = pathsFor(request.root, request.runId);
   731	  const entrypoint = process.argv[1];
   732	  if (!entrypoint) throw new Error('managed host run: cannot resolve the current lattice CLI entrypoint');
   733	  const logFd = openSync(paths.workerLog, 'a', 0o600);
   734	  try {
   735	    const child = spawn(
   736	      process.execPath,
   737	      [entrypoint, '--root', request.root, 'host_run_worker', JSON.stringify({ runId: request.runId })],
   738	      {
   739	        cwd: request.root,
   740	        env: process.env,
   741	        detached: true,
   742	        stdio: ['ignore', logFd, logFd],
   743	      },
   744	    );
   745	    if (!child.pid) throw new Error('managed host run: detached worker did not expose a pid');
   746	    child.unref();
   747	    return { pid: child.pid };
   748	  } finally {
   749	    closeSync(logFd);
   750	  }
   751	};
