   217	export function classifyProviderRegistryLock(snapshot: ExistingMkdirLockSnapshot): ExistingMkdirLockState {
   218	  const holder = snapshot.holder;
   219	  if (!holder || holder.hostname !== hostname()) return 'unknown';
   220	  if (!Number.isInteger(holder.pid) || holder.pid <= 0) return 'unknown';
   221	  try {
   222	    process.kill(holder.pid, 0);
   223	  } catch (error) {
   224	    const code = (error as NodeJS.ErrnoException).code;
   225	    if (code === 'ESRCH') return 'stale';
   226	    if (code !== 'EPERM') return 'unknown';
   227	  }
   228	  if (
   229	    holder.pid === process.pid
   230	    && !sameProcessStart(holder.processStartTimeMs, currentProcessStartTimeMs())
   231	  ) return 'stale';
   232	  return 'active';
   233	}
