   235	function withProviderRegistryLock<T>(
   236	  dir: string,
   237	  fn: () => T,
   238	  timing: ProviderRegistryLockTiming = {},
   239	): T {
   240	  const lock = acquireMkdirLock(`${dir}.lock`, {
   241	    label: 'provider-process-registry',
   242	    deadlineMs: timing.deadlineMs ?? 30_000,
   243	    staleMs: timing.staleMs ?? 10_000,
   244	    pollMs: timing.pollMs ?? 10,
   245	    requireHolderToken: true,
   246	    classifyExistingLock: classifyProviderRegistryLock,
   247	    holderInfo: {
   248	      pid: process.pid,
   249	      hostname: hostname(),
   250	      command: 'provider-process-registry mutation',
   251	      acquiredAt: new Date().toISOString(),
   252	      lockId: randomUUID(),
   253	      processStartTimeMs: currentProcessStartTimeMs(),
   254	    },
   255	  });
   256	  try {
   257	    return fn();
   258	  } finally {
   259	    lock.release();
   260	  }
