   272	export function acquireProviderProcessSlot(
   273	  dir: string,
   274	  cap: number,
   275	  staleMs: number,
   276	  now: number,
   277	  meta: ProviderProcessSlotMeta,
   278	  lockTiming: ProviderRegistryLockTiming = {},
   279	): AcquiredProviderProcessSlot | null {
   280	  mkdirSync(dir, { recursive: true });
   281	  const boundedCap = Number.isFinite(cap) && Number.isInteger(cap) && cap > 0
   282	    ? cap
   283	    : PROVIDER_PROCESS_MAX_CONCURRENT_DEFAULT;
   284	  return withProviderRegistryLock(dir, () => {
   285	    const live = scanLiveProviderProcessSlotsUnlocked(dir, now, staleMs);
   286	    if (live.length >= boundedCap) return null;
   287	    const token = randomUUID();
   288	    const record: ProviderProcessSlotFileMeta = { ...meta, token };
   289	    for (let index = 0; index < boundedCap; index += 1) {
   290	      const file = join(dir, `slot-${index}.json`);
   291	      if (writeProviderProcessSlotExclusive(file, record)) return { file, token };
   292	      const judged = readSlotOccupant(file);
   293	      if (!slotReclaimable(judged, file, now, staleMs)) continue;
   294	      if (judged.state !== 'missing') {
   295	        if (!sameSlotOccupant(readSlotOccupant(file), judged)) continue;
   296	        try { unlinkSync(file); } catch { /* exclusive recreate decides the winner */ }
   297	      }
   298	      if (writeProviderProcessSlotExclusive(file, record)) return { file, token };
   299	    }
   300	    return null;
   301	  }, lockTiming);
   302	}
