   304	export function releaseProviderProcessSlot(
   305	  file: string | null,
   306	  token: string | null,
   307	  lockTiming: ProviderRegistryLockTiming = {},
   308	): void {
   309	  if (!file || !token) return;
   310	  const dir = dirname(file);
   311	  try {
   312	    withProviderRegistryLock(dir, () => {
   313	      try {
   314	        const occupant = readSlotOccupant(file);
   315	        if (occupant.state !== 'valid' || occupant.token !== token) return;
   316	        unlinkSync(file);
   317	      } catch {
   318	        // Best effort: pid-death or corrupt-meta staleness will reclaim a leak.
   319	      }
   320	    }, lockTiming);
   321	  } catch {
   322	    // Best effort: a later acquire reclaims this slot after the holder exits.
   323	  }
   324	}
