   152	/** Format the single stderr usage-summary / refusal line. */
   153	function formatUsageLine(result: HostRunResult): string {
   154	  const u = result.usageSummary;
   155	  if (result.blocked) {
   156	    if (result.refusalReason === 'concurrency_cap_exceeded') {
   157	      const list = (result.liveRuns ?? [])
   158	        .map((r) => `  - pid ${r.pid} ${r.host}${r.storyId ? ` story ${r.storyId}` : ''} agentType ${r.agentType} startedAt ${r.startedAt}`)
   159	        .join('\n');
   160	      return `host_run refused: ${u.reason ?? 'concurrency_cap_exceeded'}${list ? `\n${list}` : ''}`;
   161	    }
   162	    return `host_run refused: ${u.reason ?? result.refusalReason ?? 'blocked'}`;
   163	  }
   164	  if (u.recorded === 'disabled') return 'usage ledger disabled (LATTICE_USAGE_LEDGER=0); no rows recorded';
   165	  if (u.recorded === 'provider-reported') {
   166	    const recordId = u.recordId ? ` (recordId ${u.recordId})` : '';
   167	    return `usage recorded: provider=${u.provider ?? 'unknown'} input=${u.input ?? 'null'} cacheRead=${u.cacheRead ?? 'null'} output=${u.output ?? 'null'}${recordId}`;
   168	  }
   169	  if (u.recorded === 'unavailable') {
   170	    return `usage recorded: unavailable (${u.reason ?? 'no usage surface'})`;
   171	  }
   172	  return `usage: ${u.reason ?? 'not recorded'}`;
   173	}
